"""Build the small school shell. Imported teaching units remain self-contained."""
from pathlib import Path
from html import escape

ROOT = Path(__file__).resolve().parents[1]
SITE = ROOT / 'site'

def svg(body, view='0 0 400 220', label=''):
    return f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="{view}" role="img" aria-label="{escape(label)}">{body}</svg>'

coil_body = '''<defs><marker id="arrow" markerWidth="7" markerHeight="7" refX="5" refY="3" orient="auto"><path d="M0 0L6 3L0 6" fill="none" stroke="#65866a" stroke-width="1.2"/></marker></defs>
<g fill="none" stroke="#8ca98b" stroke-width="1.4"><path d="M75 110C25 0 375 0 325 110"/><path d="M75 110C5 -30 395 -30 325 110"/><path d="M75 110C25 220 375 220 325 110"/><path d="M75 110C5 250 395 250 325 110"/></g>
<path d="M230 27H175M230 193H175" stroke="#65866a" marker-end="url(#arrow)"/>
<rect x="86" y="78" width="228" height="64" rx="30" fill="#9dad98" fill-opacity=".3" stroke="#82947c"/>
<g fill="none" stroke="#b77c49" stroke-width="6" stroke-linecap="round">'''+''.join(f'<path d="M{x} 147C{x-26} 150 {x-26} 70 {x} 70C{x+26} 70 {x+26} 150 {x+18} 147"/>' for x in range(100,300,22))+'''</g>
<path d="M115 110H285" stroke="#356549" stroke-width="2" marker-end="url(#arrow)"/>
<text x="53" y="116" fill="#537887" font-size="20" font-family="sans-serif">S</text><text x="338" y="116" fill="#b56d47" font-size="20" font-family="sans-serif">N</text>'''
coil = svg(coil_body,label='Eine kupferfarbene Spule. Innen zeigt das Feld nach rechts, außen führen die Feldlinien zum Südpol zurück.')
parabola = svg('''<g stroke="#b0aec8" stroke-width="1"><path d="M45 155H355M200 25V200"/><path d="M85 40V190M142 40V190M258 40V190M315 40V190M60 98H340" opacity=".3"/></g><path d="M90 35Q200 310 310 35" stroke="#7d73a3" stroke-width="4" fill="none"/><g fill="#9c8abc" stroke="#f0ebf6" stroke-width="4"><circle cx="137" cy="155" r="7"/><circle cx="263" cy="155" r="7"/></g><text x="275" y="60" fill="#7b6e94" font-size="22" font-family="Georgia,serif" font-style="italic">y = x² − 4</text>''',label='Eine Parabel schneidet die x-Achse an zwei Nullstellen.')
picture = svg('''<rect x="78" y="28" width="244" height="164" rx="4" fill="#fbf4e4" stroke="#bda57c" stroke-width="2"/><circle cx="264" cy="72" r="20" fill="#e5bd6e"/><path d="M80 155L146 86L209 155L253 110L320 168V190H80Z" fill="#9bad91"/><path d="M80 172L173 129L238 190H80" fill="#6d8876"/><path d="M103 43V65M92 54H114M294 154V176M283 165H305" stroke="#b7a080" stroke-width="1.5"/><path d="M54 103H102M298 103H346" stroke="#c3ac84" stroke-dasharray="3 4"/>''',label='Eine Landschaft in einem Bilderrahmen mit markierten Bildbereichen.')
clock = svg('''<circle cx="153" cy="110" r="72" fill="#f9f3e8" stroke="#c59b64" stroke-width="2"/><path d="M153 110V63M153 110L190 130" stroke="#aa7946" stroke-width="4" stroke-linecap="round"/><circle cx="153" cy="110" r="5" fill="#aa7946"/><g fill="#8b775c" font-size="14" font-family="sans-serif"><text x="144" y="55">12</text><text x="209" y="115">3</text><text x="149" y="175">6</text><text x="89" y="115">9</text></g><rect x="241" y="60" width="100" height="100" rx="6" fill="#eee0c8"/><text x="262" y="103" fill="#9b7043" font-size="32" font-family="Georgia">90</text><text x="263" y="133" fill="#9b7043" font-size="14" font-family="sans-serif">Minuten</text>''',label='Eine Uhr neben einem 90-Minuten-Unterrichtsplan.')
movement = svg('''<path d="M55 175Q140 175 155 110T270 65Q335 80 330 175" stroke="#a4b8b1" fill="none" stroke-width="2" stroke-dasharray="5 7"/><circle cx="200" cy="54" r="16" fill="#648c80"/><g fill="none" stroke="#648c80" stroke-width="12" stroke-linecap="round"><path d="M200 84L181 125L150 162M184 119L230 132L245 170M196 89L161 95L139 73M195 88L232 76L250 48"/></g><circle cx="298" cy="163" r="21" fill="#d7bd81"/><path d="M60 186H350" stroke="#b5c7bc"/>''',label='Eine laufende Figur mit Bewegungsweg und Ball.')
chemistry = svg('''<rect x="162" y="25" width="76" height="174" rx="13" fill="#dae8eb" stroke="#74939c" stroke-width="2"/><g stroke="#8ba9ac" stroke-width="2">'''+''.join(f'<path d="M163 {y}H222L238 {y-8}"/>' for y in range(60,180,25))+'''</g><path d="M165 170H236V186Q235 197 225 197H175Q165 197 165 185Z" fill="#b4cfcc"/><path d="M200 24V13H295V55" fill="none" stroke="#74939c" stroke-width="3"/><path d="M70 128H162M238 178H319" stroke="#74939c" stroke-width="3"/><path d="M188 160V55M215 62V162" fill="none" stroke="#b78d65" stroke-width="3"/><path d="M182 63L188 54L194 63M209 153L215 162L221 153" fill="none" stroke="#b78d65" stroke-width="2"/><text x="51" y="112" font-size="14" fill="#72898c" font-family="sans-serif">Gemisch</text>''',label='Eine Trennkolonne mit aufsteigendem Dampf und absteigender Flüssigkeit.')

header = '''<a class="skip" href="#main">Zum Inhalt</a><header class="site-header"><div class="wrap header-inner"><a href="/" class="brand"><span class="brand-mark">s</span>school<span><small>by logge</small></span></a><nav class="site-nav" aria-label="Hauptnavigation"><a href="/#faecher">Lerninhalte</a><a href="/#unterricht">Für den Unterricht</a></nav></div></header>'''
footer = '''<footer class="site-footer"><div class="wrap footer-inner"><span>school.logge.top · Lernen in deinem Tempo.</span><span><a href="/">Alle Lerninhalte</a> · <a href="https://github.com/LoggeL/school">Quellcode</a></span></div></footer>'''
def page(title,body,scripts=''):
    return f'''<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#235849"><title>{title}</title><meta name="description" content="Visuelle Lerninhalte für Mathematik, Physik und Deutsch. Mit interaktiven Erklärungen, Übungen und Unterrichtsmaterial."><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/assets/school.css"></head><body>{header}{body}{footer}{scripts}</body></html>'''

cards = [
('physik','Physik','Grundlagen','Spule & Elektromagnet','Wie aus elektrischem Strom ein Magnetfeld wird. Mit 3D-Modell, Rechenwegen und Übungen.','/physik/spule-elektromagnet/','3D entdecken · 8 Rechenaufgaben',coil,'#e9eee1','#547454'),
('mathematik','Mathematik','Klasse 9','Quadratische Gleichungen','Parabeln verstehen, Nullstellen finden und Gleichungen auf drei Wegen lösen.','/quadratische-gleichungen/','Lernpfad · Trainer · Selbsttests',parabola,'#eeebf5','#80709e'),
('deutsch unterricht','Deutsch','Klasse 5','Bilder genau beschreiben','Vom ersten Blick zum geordneten Text. Mit Bildwelten, Wortschatz und Lernspielen.','/bildbeschreibung-klasse5/','Lernspiele · Arbeitsblätter',picture,'#f3eddf','#a1844e'),
('mathematik unterricht','Mathematik','Unterricht','90 Minuten Nachhilfe','Ein kompletter Stundenplan zu quadratischen Gleichungen. Schritt für Schritt durchs Thema.','/nachhilfe-quadratische-gleichungen/','Stundenplan · Aufgaben · Lösungen',clock,'#f4ebdf','#9c7c51'),
('paedagogik unterricht','Pädagogik','Unterricht','Bewegungserziehung','Spiel, Bewegung und Haltung: Grundlagen, Beispiele und Impulse für die Praxis.','/bewegungserziehung-uw1/','Fachwissen · Praxisimpulse',movement,'#e8eeea','#638278'),
('chemie','Chemie & Technik','Vertiefung','Stoffgemische trennen','Eine Trennkolonne ausprobieren und beobachten, wie sich das Gemisch aufteilt.','/rectify-trennkolonne/','Simulation · Szenarien',chemistry,'#e8eef0','#6c8993')
]
cardhtml=''
for subject,cat,level,title,desc,link,meta,art,tint,accent in cards:
    art=art.replace('id="arrow"', 'id="card-arrow"').replace('url(#arrow)', 'url(#card-arrow)')
    cardhtml+=f'<a class="card" data-subject="{subject}" href="{link}" style="--tint:{tint};--accent:{accent}"><div class="card-art">{art}</div><div class="card-content"><div class="card-meta"><span>{cat}</span><span>{level}</span></div><h3>{title}</h3><p>{desc}</p><div class="card-footer"><span>{meta}</span><b aria-hidden="true">↗</b></div></div></a>'
filters=''.join(f'<button class="filter" type="button" data-filter="{key}" aria-pressed="{str(key=="alle").lower()}">{label}</button>' for key,label in [('alle','Alle Fächer'),('mathematik','Mathematik'),('physik','Physik'),('deutsch','Deutsch'),('paedagogik','Pädagogik'),('chemie','Chemie & Technik'),('unterricht','Unterrichtsmaterial')])
home=f'''<main id="main"><div class="wrap"><section class="hero"><div><p class="eyebrow">Ansehen. Ausprobieren. Verstehen.</p><h1>Manches versteht<br>man besser<br><em>mit einem Bild.</em></h1><p class="lead">Dein Lernort für Mathe, Physik und mehr. Entdecke Zusammenhänge, rechne selbst und finde deinen Weg zur Lösung.</p><div class="hero-actions"><a class="button" href="/physik/spule-elektromagnet/">Physik entdecken <span aria-hidden="true">↗</span></a><a class="text-link" href="#faecher">Alle Lerninhalte</a></div><p class="hero-note">Ohne Anmeldung. Direkt loslernen.</p></div><div class="feature-art"><div class="art-top"><span class="pill">Neu · Physik</span><span>Was macht die Spule magnetisch?</span></div><div class="hero-svg">{coil}</div><div class="art-bottom"><span><strong>Strom an. Magnetfeld da.</strong><br>Ein unsichtbarer Zusammenhang wird sichtbar.</span><span aria-hidden="true">N ↔ S</span></div></div></section><section class="library" id="faecher"><div class="section-heading"><div><p class="eyebrow">Womit möchtest du anfangen?</p><h2>Ein Thema. Dein nächster Aha-Moment.</h2></div><p id="result-count" aria-live="polite">6 Lerneinheiten</p></div><div class="filters" role="group" aria-label="Nach Fach filtern">{filters}</div><div class="grid">{cardhtml}</div></section><section class="study-strip" id="unterricht"><div><p class="eyebrow">Für dich & deinen Unterricht</p><h2>Erst sehen.<br>Dann selbst können.</h2><p>Vom anschaulichen Modell bis zum eigenen Lösungsweg.</p></div><div class="study-steps"><div><b>01</b><h3>Entdecken</h3><p>Skizzen und Modelle machen Zusammenhänge greifbar.</p></div><div><b>02</b><h3>Ausprobieren</h3><p>Verändere eine Größe und beobachte, was passiert.</p></div><div><b>03</b><h3>Anwenden</h3><p>Rechne selbst. Die Lösung hilft dir Schritt für Schritt.</p></div></div></section></div></main>'''
(SITE/'index.html').write_text(page('school · Verstehen mit einem Bild',home,'<script src="/assets/home.js" defer></script>'))
(SITE/'assets/favicon.svg').write_text(svg('<rect width="64" height="64" rx="14" fill="#235849"/><text x="22" y="46" fill="#fff" font-size="50" font-family="Georgia" font-style="italic">s</text>','0 0 64 64','school'))
(SITE/'404.html').write_text(page('Seite nicht gefunden · school','<main id="main" class="wrap lesson-hero"><p class="eyebrow">404</p><h1>Hier fehlt eine Seite.</h1><p class="lead">Über die Übersicht findest du alle Lerninhalte.</p><a class="button" href="/">Zur Lernübersicht</a></main>'))

if __name__ == '__main__':
    print('Built homepage and 404 page.')
